#include "tigersheets/pivot_fields_pane.hpp"
#include <QApplication>
#include <QComboBox>
#include <QLineEdit>
#include <QLabel>
#include <QListWidget>
#include <QPushButton>
#include <QTableWidget>
#include <QTest>
#include <iostream>
#include <stdexcept>
using namespace tigersheets;
namespace {
void require(bool condition,const char* message){if(!condition)throw std::runtime_error(message);}
Json sheets(){return Json::parse(R"([{"id":"s","name":"Data"},{"id":"r","name":"Report"}])");}
Json fields(){return Json::parse(R"([{"name":"Region","numberFormat":"General","items":[{"type":"number","value":123},{"type":"string","value":"123"},{"type":"blank","value":null}]},{"name":"Date","numberFormat":"m/d/yyyy"},{"name":"Revenue","numberFormat":"#,##0.00"}])");}
Json definition(){return Json::parse(R"({"id":"p","name":"RevenueReport","source":{"sheet":"s","row1":1,"col1":1,"row2":10,"col2":3},"rows":[{"field":"Region"},{"field":"Date","group":"month"}],"columns":[],"filters":[],"values":[{"field":"Revenue","aggregate":"sum","name":"Revenue","numberFormat":"#,##0.00"}],"output":{"sheet":"r","row1":2,"col1":4},"rowGrandTotals":true,"columnGrandTotals":false})");}
void fieldOrderAndNativeControls(){PivotFieldsPane pane;pane.setDefinition(definition(),sheets(),fields());pane.show();QApplication::processEvents();auto* rows=pane.findChild<QListWidget*>("pivot.rows");auto* values=pane.findChild<QTableWidget*>("pivot.values");require(rows&&values&&rows->count()==2&&values->rowCount()==1,"Native field buckets and measure controls must load the report");rows->setFocus();rows->setCurrentRow(0);QTest::keyClick(rows,Qt::Key_Down,Qt::AltModifier);require(pane.definition()["rows"][1]["field"]=="Region","Alt+Down reorders a row field");QTest::keyClick(rows,Qt::Key_Delete);require(pane.definition()["rows"].size()==1&&pane.definition()["rows"][0]["field"]=="Date","Delete removes only the selected bucket field");auto* grouping=pane.findChild<QComboBox*>("pivot.dateGroup");rows->setCurrentRow(0);grouping->setCurrentIndex(grouping->findData("year"));require(pane.definition()["rows"][0]["group"]=="year","Date grouping is a native typed choice");
 bool applied=false;pane.applyRequested=[&](const Json& value){applied=value["values"][0]["aggregate"]=="average";};auto* aggregate=qobject_cast<QComboBox*>(values->cellWidget(0,1));aggregate->setCurrentIndex(aggregate->findData("average"));pane.findChild<QPushButton*>("pivot.apply")->click();require(applied,"Apply sends the editable report specification through its callback");require(pane.findChild<QLineEdit*>("pivot.sourceRange")->text()=="A1:C10","Source range displays real worksheet addresses");require(pane.definition()["output"]["sheet"]=="r"&&pane.definition()["columnGrandTotals"]==false,"Destination identity and totals survive editing");
}
void boundedMemberSearchPreservesHiddenSelections(){
 PivotFieldsPane pane;auto spec=definition();spec["filters"]=Json::parse(R"([{"field":"Region","all":false,"items":[{"type":"string","value":"Case0"}]}])");auto descriptors=fields();descriptors[0]["items"]=Json::array();for(int i=0;i<200;++i)descriptors[0]["items"].push_back({{"type","string"},{"value","Case"+std::to_string(i)}});pane.setDefinition(spec,sheets(),descriptors);bool searched=false;
 pane.memberSearchRequested=[&](QString field,QString query){if(field=="Region"&&query=="Case99999"){searched=true;pane.setMemberResults(field,Json::array({{{"type","string"},{"value","Case99999"}}}),100000);}};
 pane.findChild<QLineEdit*>("pivot.memberSearch")->setText("Case99999");auto* members=pane.findChild<QListWidget*>("pivot.members");require(searched&&members->count()==1&&members->item(0)->text().contains("Case99999"),"Search must request bounded results from the complete cache, beyond the first200 members");members->item(0)->setCheckState(Qt::Checked);const auto selected=pane.definition()["filters"][0]["items"];require(selected.size()==2,"Selections outside the displayed search window must remain intact");
}
void typedFiltersAndDestinationCallbacks(){
 PivotFieldsPane pane;auto spec=definition();spec["filters"]=Json::parse(R"([{"field":"Region","all":false,"items":[{"type":"string","value":"123"},{"type":"blank","value":null},{"type":"string","value":"Gone"}],"missingItems":[{"type":"string","value":"Gone"}]}])");pane.setDefinition(spec,sheets(),fields());auto* members=pane.findChild<QListWidget*>("pivot.members");require(members->count()==4,"Typed filter contains numeric, text, blank and missing members");bool missingDisabled=false;for(int i=0;i<members->count();++i){auto* member=members->item(i);if(member->text().contains("[missing]"))missingDisabled=!(member->flags()&Qt::ItemIsEnabled)&&member->checkState()==Qt::Checked;if(member->text().contains("[number]"))member->setCheckState(Qt::Checked);}require(missingDisabled&&pane.definition()["filters"][0]["items"].size()==4,"Missing members stay visibly disabled and typed selections remain distinct");auto* mode=pane.findChild<QComboBox*>("pivot.filterMode");mode->setCurrentIndex(mode->findData("all"));require(pane.definition()["filters"][0]["all"]==true,"All members is an explicit filter mode");
 pane.findChild<QComboBox*>("pivot.destination")->setCurrentIndex(0);pane.findChild<QLineEdit*>("pivot.outputCell")->setText("F8");auto updated=pane.definition();require(updated["newWorksheet"]==true&&updated["output"]["sheet"]==""&&updated["output"]["row1"]==8&&updated["output"]["col1"]==6,"A new-sheet destination remains a reviewable request for the host");bool source=false,removed=false;QString chart;pane.sourceRequested=[&](QString sheet,QString range){source=sheet=="s"&&range=="A1:C10";};pane.deleteRequested=[&]{removed=true;};pane.insertChartRequested=[&](QString type){chart=type;};pane.findChild<QPushButton*>("pivot.readSource")->click();pane.findChild<QComboBox*>("pivot.chartType")->setCurrentIndex(2);pane.findChild<QPushButton*>("pivot.insertChart")->click();pane.findChild<QPushButton*>("pivot.delete")->click();require(source&&removed&&chart=="bar","Source, chart and delete commands remain explicit native callbacks");
}
void refreshStatusPreservesDraft(){PivotFieldsPane pane;auto spec=definition();spec["stale"]=true;spec["provenance"]={{"links",Json::array({{{"name","Drivers.xlsx"},{"state","cached"}},{{"name","Budget.xlsx"},{"state","unavailable"}}})}};pane.setDefinition(spec,sheets(),fields());auto* status=pane.findChild<QLabel*>("pivot.status");require(status&&status->text().contains("Needs refresh")&&status->text().contains("Drivers.xlsx")&&status->text().contains("cached")&&status->text().contains("unavailable"),"pane exposes refresh status and saved/unavailable financial link provenance");require(!status->accessibleName().isEmpty()&&status->textFormat()==Qt::PlainText,"report status has an accessible plain-text label");pane.findChild<QLineEdit*>("pivot.name")->setText("Unapplied draft");pane.findChild<QLineEdit*>("pivot.outputCell")->setText("H20");const auto draft=pane.definition();pane.setStatus({{"stale",false},{"provenance",{{"links",Json::array({{{"name","Drivers.xlsx"},{"state","fresh"}}})}}}});require(status->text().contains("current")&&status->text().contains("fresh")&&!status->text().contains("unavailable")&&pane.definition()==draft,"bounded status updates preserve unapplied fields, output and draft controls");}
}
int main(int argc,char**argv){QApplication app(argc,argv);try{fieldOrderAndNativeControls();boundedMemberSearchPreservesHiddenSelections();typedFiltersAndDestinationCallbacks();refreshStatusPreservesDraft();std::cout<<"pivot fields pane tests passed\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
